def approve_what_already_passed(apps, schema_editor):
    """Before REQ-M.182 the script's pass was the pass.

    Everyone whose profile already carries `entrance_test_passed_at` was let in
    on that basis, so their passing attempts are recorded as approved, by nobody
    (decided_by stays empty: it was the script). Without this, every existing
    member's attempt would read "waiting for the team" on the review screen.
    """
    Attempt = apps.get_model("matazim", "EntranceAttempt")
    Attempt.objects.filter(
        passed=True, submitted_at__isnull=False,
        member__entrance_test_passed_at__isnull=False,
    ).update(decision="approved")


